validator:
function validate(input) {
  const [{ students = [] }] = input;
  const ids = new Set();
  for (const [id, name, age, grade] of students) {
    if (id === null) return 'Every student needs a student_id.';
    if (ids.has(id)) return `student_id ${id} appears twice.`;
    ids.add(id);
    if (name === null) return 'Every student needs a name.';
    if (age === null) return 'age cannot be null.';
    if (grade === null) return 'grade cannot be null.';
    if (grade < 0) return 'grade cannot be negative.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Ava', 'Kate', 'Liam', 'Noah', 'Emma', 'Mia', 'Owen', 'Zara'];
  const marks = [0, 0.5, 49.99, 59.5, 73, 87, 87.9, 99.99, 100];
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const students = [];
  for (let i = 0; i < rows; i++) {
    const grade = size === 'small' && rand() < 0.6 ? pick(marks) : rand() < 0.4 ? Math.floor(rand() * 101) : Math.round(rand() * 10000) / 100;
    students.push([i + 1, pick(names), 5 + Math.floor(rand() * 16), grade]);
  }
  return [{ students }];
}
